/**
 * The presets offered in the theme picker.
 *
 * A curated list rather than a colour picker, and the generator enforces
 * why: only hues in 65-110 and 195-265 keep all four category accents at
 * least 40 degrees apart once the fixed error red is counted.
 */
enum class ThemeSeed(
    val label: String,
    val light: ColorScheme,
    val dark: ColorScheme,
) {
    WADA("Wada", WadaLight, WadaDark),
    WABI("Wabi", WabiLight, WabiDark),
    FOOL("Fool", FoolLight, FoolDark),
    GASLAMP("Gaslamp", GaslampLight, GaslampDark),
    TYRANT("Tyrant", TyrantLight, TyrantDark),
    ABYSS("Abyss", AbyssLight, AbyssDark),
}
